  public static Model run()throws Exception {
    Model m=ModelUtil.create("free_coreshell_pfp_gel_3d");
    m.label("Theory 2: full 3D PFP/gel finite-energy coupling - freely responding radius and shape");m.modelPath(ROOT+"scratch");
    m.param().set("a","300[nm]","Reference cavity radius");
    m.param().set("B","20","Outer radius / cavity radius");m.param().set("BK","1000","Bulk/shear modulus control");
    m.param().set("G","10[kPa]","Reference PAAm shear modulus; E approximately 30 kPa");m.param().set("lam","1.8","Analytic verification target and initial guess only; no displacement constraint");
    m.component().create("c",true);m.component("c").geom().create("g",3);
    for(String s:new String[]{"outer","inner"}) {m.component("c").geom("g").create(s,"Sphere");m.component("c").geom("g").feature(s).set("r",s.equals("outer")?"B*a":"a");}
    m.component("c").geom("g").create("dif","Difference");m.component("c").geom("g").feature("dif").selection("input").set("outer");m.component("c").geom("g").feature("dif").selection("input2").set("inner");m.component("c").geom("g").run();
    m.component("c").selection().create("cavity","Box");m.component("c").selection("cavity").set("entitydim",2);m.component("c").selection("cavity").set("condition","inside");
    for(String q:new String[]{"x","y","z"}) {m.component("c").selection("cavity").set(q+"min","-1.001*a");m.component("c").selection("cavity").set(q+"max","1.001*a");}
    System.out.println("CAVITY="+Arrays.toString(m.component("c").selection("cavity").entities(2)));
    m.save(ROOT+"scratch/free_coreshell3d_geometry.mph");
    m.component("c").physics().create("solid","SolidMechanics","g");m.component("c").physics("solid").create("hyp","HyperelasticModel",3);m.component("c").physics("solid").feature("hyp").selection().all();
    m.component("c").physics("solid").feature("hyp").set("MaterialModel","NeoHookean");
    m.component("c").physics("solid").feature("hyp").set("Compressibility_NeoHookean","NearlyIncompressible");
    m.component("c").physics("solid").feature("hyp").set("MixedFormulation","pFormulation");m.component("c").physics("solid").feature("hyp").set("IsotropicOption","KG");
    m.component("c").physics("solid").feature("hyp").set("kappa","BK*G");
    m.component("c").physics("solid").feature("hyp").set("G_mat","userdef");m.component("c").physics("solid").feature("hyp").set("G","G");
    m.component("c").physics("solid").feature("hyp").set("K_mat","userdef");m.component("c").physics("solid").feature("hyp").set("K","BK*G");
    m.component("c").physics("solid").feature("hyp").set("rho_mat","userdef");m.component("c").physics("solid").feature("hyp").set("rho","1006.5[kg/m^3]");
    String f="(((X^2+Y^2+Z^2)^(3/2)+a^3*(lam^3-1))^(1/3)/sqrt(X^2+Y^2+Z^2)-1)";
    m.component("c").physics("solid").feature("init1").set("u",new String[]{f+"*X",f+"*Y",f+"*Z"});
    m.component("c").cpl().create("ic","Integration");m.component("c").cpl("ic").selection().geom("g",2);m.component("c").cpl("ic").selection().named("cavity");m.component("c").cpl("ic").set("frame","material");
    m.component("c").cpl().create("iv","Integration");m.component("c").cpl("iv").selection().geom("g",3);m.component("c").cpl("iv").selection().all();m.component("c").cpl("iv").set("frame","material");
    m.component("c").mesh().create("mesh","g");
    m.component("c").mesh("mesh").feature("size").set("custom",true);m.component("c").mesh("mesh").feature("size").set("hmax","B*a/4");
    m.component("c").mesh("mesh").feature("size").set("hmin","a/4");m.component("c").mesh("mesh").feature("size").set("hgrad",1.6);m.component("c").mesh("mesh").feature("size").set("hcurve",0.25);
    m.component("c").mesh("mesh").create("local","Size");m.component("c").mesh("mesh").feature("local").selection().geom("g",2);m.component("c").mesh("mesh").feature("local").selection().named("cavity");
    m.component("c").mesh("mesh").feature("local").set("custom",true);m.component("c").mesh("mesh").feature("local").set("hmaxactive",true);m.component("c").mesh("mesh").feature("local").set("hmax","a/3");
    m.component("c").mesh("mesh").create("tet","FreeTet");m.component("c").mesh("mesh").run();m.save(ROOT+"scratch/free_coreshell3d_meshed.mph");

    m.param().set("sigTest","sigLL","Reference constant surface energy coefficient");
    m.param().set("pLoad","G/2*(5-4/lam-lam^(-4))+2*sigTest/(a*lam)","Known pressure for the independent spherical elastic/capillary control");
    m.component("c").physics("solid").create("rms","RigidMotionSuppression",3);m.component("c").physics("solid").feature("rms").selection().all();
    m.component("c").physics("solid").create("pressure","BoundaryLoad",2);m.component("c").physics("solid").feature("pressure").selection().named("cavity");m.component("c").physics("solid").feature("pressure").set("forceType","FollowerPressure");m.component("c").physics("solid").feature("pressure").set("pressure","pLP-p0");
    m.component("c").variable().create("surfenergy");
    String[] xyz={"X","Y","Z"};String[] uu={"u","v","w"};
    for(int i=0;i<3;i++)for(int j=0;j<3;j++)m.component("c").variable("surfenergy").set("F"+(i+1)+(j+1)+"p",(i==j?"1+":"")+"mean(d("+uu[i]+","+xyz[j]+"))");
    for(int i=0;i<3;i++)for(int j=0;j<3;j++) {
      int r1=(i+1)%3+1,r2=(i+2)%3+1,c1=(j+1)%3+1,c2=(j+2)%3+1;
      m.component("c").variable("surfenergy").set("CF"+(i+1)+(j+1),"F"+r1+c1+"p*F"+r2+c2+"p-F"+r1+c2+"p*F"+r2+c1+"p");
    }
    m.component("c").variable("surfenergy").set("JF","F11p*CF11+F12p*CF12+F13p*CF13");
    for(int i=1;i<=3;i++) {
      m.component("c").variable("surfenergy").set("CN"+i,"-(CF"+i+"1*X+CF"+i+"2*Y+CF"+i+"3*Z)/a");
    }
    m.component("c").variable("surfenergy").set("Js","sqrt(CN1^2+CN2^2+CN3^2)");
    for(int i=1;i<=3;i++)m.component("c").variable("surfenergy").set("ns"+i,"CN"+i+"/Js");
    String weak="";
    for(int i=1;i<=3;i++)for(int j=1;j<=3;j++) {
      String proj="CF"+i+j+"-ns"+i+"*(ns1*CF1"+j+"+ns2*CF2"+j+"+ns3*CF3"+j+")";
      weak+="-sigTest*Js/JF*("+proj+")*test(dtang("+uu[i-1]+","+xyz[j-1]+"))";
    }
    m.component("c").physics("solid").create("surface","WeakContribution",2);m.component("c").physics("solid").feature("surface").selection().named("cavity");m.component("c").physics("solid").feature("surface").set("quadratureFrame","material");m.component("c").physics("solid").feature("surface").set("weakExpression",weak);
    m.component("c").variable("surfenergy").set("Vfree","-ic((X+u)*CN1+(Y+v)*CN2+(Z+w)*CN3)/3");
    m.component("c").variable("surfenergy").set("Rfree","(3*Vfree/(4*pi))^(1/3)");m.component("c").variable("surfenergy").set("Afree","ic(Js)");
    m.param().set("Qdep","11.55[pJ]","Net retained subsystem energy after supplied activation; no optical efficiency inferred");
    installEOS(m);
    m.param().set("sigLV","0.00941[N/m]","PFP / saturated-air room-temperature reference; heated/nanoscale use is conditional");
    m.param().set("nucleusFloor","a/100","Numerical radius floor only; accepted states must be far above it");
    m.param().set("sigLL","0.054[N/m]","Pure PFP/water liquid-liquid reference; actual surfactant formulation is unresolved");
    m.param().set("Tref","293.15[K]");m.param().set("rhoLref","1621.2304497568995[kg/m^3]");m.param().set("rhoVref","8.781946533312483[kg/m^3]");
    m.param().set("ad","a","Equivalent PFP droplet radius; distinct from the preformed cavity radius a");
    m.param().set("rhoD","1623.3028161533516[kg/m^3]");m.param().set("mp","4*pi*ad^3*rhoD/3");
    m.param().set("p0","100[kPa]");m.param().set("sig","sigLL","Unused legacy alias: assumed PFP/gel outer coefficient; active loads use sigLL");
    m.param().set("lamFail","2.1","PAAm ultimate-stretch reference from Movahed 2016, not a certification of Li 2024 formulation");
    m.component("c").variable().create("thermo");
    String radial="(solid.sxx*(X/a)^2+solid.syy*(Y/a)^2+solid.szz*(Z/a)^2+2*solid.sxy*X*Y/a^2+2*solid.sxz*X*Z/a^2+2*solid.syz*Y*Z/a^2)";
    m.component("c").variable("thermo").set("pGel","pLP-p0-2*sigLL/Rfree");
    m.component("c").variable("thermo").set("Temp","Tref*theta");
    m.component("c").variable("thermo").set("rhoLP","rhoLref*exp(qL)");m.component("c").variable("thermo").set("rhoVP","rhoVref*exp(qV)");
    m.component("c").variable("thermo").set("Vb","Vfree");
    m.component("c").variable("thermo").set("pNeed","pLP");
    m.component("c").variable("thermo").set("pLP","pfpp(Temp/1[K],rhoLP/(1[kg/m^3]))*1[Pa]");m.component("c").variable("thermo").set("pVP","pfpp(Temp/1[K],rhoVP/(1[kg/m^3]))*1[Pa]");
    m.component("c").variable("thermo").set("gLP","pfpg(Temp/1[K],rhoLP/(1[kg/m^3]))*1[J/kg]");m.component("c").variable("thermo").set("gVP","pfpg(Temp/1[K],rhoVP/(1[kg/m^3]))*1[J/kg]");
    m.component("c").variable("thermo").set("uLP","pfpu(Temp/1[K],rhoLP/(1[kg/m^3]))*1[J/kg]");m.component("c").variable("thermo").set("uVP","pfpu(Temp/1[K],rhoVP/(1[kg/m^3]))*1[J/kg]");
    m.component("c").variable("thermo").set("fv","(Vb-mp/rhoLP)/(mp*(1/rhoVP-1/rhoLP))");
    m.component("c").variable("thermo").set("fvDropSized","(Vb-(4*pi*a^3*rhoD/3)/rhoLP)/((4*pi*a^3*rhoD/3)*(1/rhoVP-1/rhoLP))");
    m.component("c").variable("thermo").set("UP","mp*((1-fv)*uLP+fv*uVP)");
    m.component("c").variable("thermo").set("Vgas","fv*mp/rhoVP");
    m.component("c").variable("thermo").set("Rg","(max(Vgas,4*pi*nucleusFloor^3/3)*3/(4*pi))^(1/3)");
    m.component("c").variable("thermo").set("shellThickness","Rfree-Rg");
    m.component("c").variable("thermo").set("WsTotal","iv(solid.Ws)");
    m.component("c").variable("thermo").set("Qmin","UP-mp*pfpu(Tref/1[K],rhoD/(1[kg/m^3]))*1[J/kg]+WsTotal+p0*(Vb-4*pi*ad^3/3)+sigLL*Afree+4*pi*sigLV*Rg^2-4*pi*sigLL*ad^2");
    m.component("c").variable("thermo").set("massResidual","(rhoVP*(Vb-(1-fv)*mp/rhoLP)-fv*mp)/mp");
    m.component("c").physics().create("ge","GlobalEquations");
    m.component("c").physics("ge").feature("ge1").set("name",new String[]{"theta","qL","qV"});
    m.component("c").physics("ge").feature("ge1").set("equation",new String[]{"(pVP-pLP-2*sigLV/Rg)/p0","(gLP-gVP)/(100[kJ/kg])","(Qmin-Qdep)/(mp*100[kJ/kg])"});
    m.component("c").physics("ge").feature("ge1").set("initialValueU",new String[]{"1.1655711769961976","-0.11475258143625314","1.5473196370961337"});m.component("c").physics("ge").feature("ge1").set("initialValueUt",new String[]{"0","0","0"});


    m.component("c").cpl().create("maxd","Maximum");m.component("c").cpl("maxd").selection().geom("g",3);m.component("c").cpl("maxd").selection().all();
    m.component("c").variable().create("post");m.component("c").variable("post").set("stretch","Rfree/a");
    String[] coords={"X","Y","Z"};String[] disp={"u","v","w"};
    for(int i=0;i<3;i++)for(int j=0;j<3;j++)m.component("c").variable("post").set("F"+(i+1)+(j+1)+"d",(i==j?"1+":"")+"d("+disp[i]+","+coords[j]+")");
    for(int i=1;i<=3;i++)for(int j=i;j<=3;j++) {
      String e="";for(int k=1;k<=3;k++)e+=(k>1?"+":"")+"F"+k+i+"d*F"+k+j+"d";
      m.component("c").variable("post").set("C"+i+j+"d",e);
    }
    m.component("c").variable("post").set("qd","(C11d+C22d+C33d)/3");m.component("c").variable("post").set("pd","sqrt(max(1e-24,((C11d-qd)^2+(C22d-qd)^2+(C33d-qd)^2+2*(C12d^2+C13d^2+C23d^2))/6))");
    String det="(C11d-qd)*(C22d-qd)*(C33d-qd)+2*C12d*C13d*C23d-(C11d-qd)*C23d^2-(C22d-qd)*C13d^2-(C33d-qd)*C12d^2";
    m.component("c").variable("post").set("rd","min(1,max(-1,("+det+")/(2*pd^3)))");m.component("c").variable("post").set("stretchMax","sqrt(max(0,qd+2*pd*cos(acos(rd)/3)))");
    m.study().create("std");m.study("std").label("Retained-energy-driven partial PFP phase state and unconstrained 3D gel deformation");m.study("std").create("stat","Stationary");m.study("std").feature("stat").set("geometricNonlinearity",true);
    m.study("std").feature("stat").set("useparam","on");m.study("std").feature("stat").set("pname",new String[]{"Qdep"});m.study("std").feature("stat").set("plistarr",new String[]{"11.55 11.65 11.75 11.82 11.9"});m.study("std").feature("stat").set("punit",new String[]{"pJ"});m.study("std").feature("stat").set("preusesol","yes");m.study("std").createAutoSequences("all");
    m.sol("sol1").feature("v1").feature("c_u").set("scalemethod","manual");m.sol("sol1").feature("v1").feature("c_u").set("scaleval","a");m.sol("sol1").feature("v1").feature("c_solid_hyp_pw").set("scalemethod","manual");m.sol("sol1").feature("v1").feature("c_solid_hyp_pw").set("scaleval","G");m.sol("sol1").feature("v1").feature("c_ODE1").set("scalemethod","manual");m.sol("sol1").feature("v1").feature("c_ODE1").set("scaleval","1");
    m.sol("sol1").feature("s1").create("directAll","Direct");m.sol("sol1").feature("s1").feature("directAll").set("linsolver","pardiso");m.sol("sol1").feature("s1").create("coupledAll","FullyCoupled");m.sol("sol1").feature("s1").feature("coupledAll").set("linsolver","directAll");m.sol("sol1").feature("s1").feature("coupledAll").set("maxiter",50);m.sol("sol1").feature("s1").set("stol","1e-7");
    if(Arrays.asList(m.sol("sol1").feature("s1").feature().tags()).contains("se1"))m.sol("sol1").feature("s1").feature().remove("se1");
    m.save(ROOT+"scratch/free_coreshell3d_configured.mph");try{m.sol("sol1").runAll();}catch(Exception e){m.save(ROOT+"scratch/free_coreshell3d_failed.mph");throw e;}
    m.save(ROOT+"scratch/free_coreshell3d_solved.mph");
    m.result().table().create("tbl","Table");m.result().numerical().create("eval","EvalGlobal");m.result().numerical("eval").set("table","tbl");
    String[] ex={"Qdep","c.stretch","c.Temp","c.pLP","c.pVP","c.rhoLP","c.rhoVP","c.fv","c.Rg","c.shellThickness","c.Qmin","(c.Qmin-Qdep)/Qdep","c.massResidual","c.pVP-c.pLP-2*sigLV/c.Rg","c.gLP-c.gVP","c.pGel","G/2*(5-4/c.stretch-c.stretch^(-4))","c.WsTotal","2*pi*G*a^3*(5*c.stretch^3/3-2*c.stretch^2+1/c.stretch-2/3)","c.Afree/(4*pi*c.Rfree^2)","c.maxd(c.stretchMax)","c.maxd(c.stretchMax)/lamFail","c.Rg/nucleusFloor"};
    m.result().numerical("eval").set("expr",ex);m.result().numerical("eval").set("descr",ex);m.result().numerical("eval").setResult();m.result().table("tbl").save(ROOT+"data/free_coreshell3d_control.csv");m.save(ROOT+"scratch/free_coreshell3d_solved.mph");System.out.println("FREE_ENERGY_PFP_GEL_3D_SOLVED="+Arrays.toString(m.sol("sol1").getSize()));return m;
  }
